1	//! The shared host side of the offload: one [`PegaEngine`], the tokio runtime
2	//! that drives it, and the optional P2P serving lifecycle.
3	
4	use std::sync::Arc;
5	
6	use pegaflow_core::EngineError;
7	use pegaflow_core::P2pTransferService;
8	use pegaflow_core::PegaEngine;
9	use pegaflow_core::StorageConfig;
10	use tokio::runtime::Runtime;
11	use tokio::sync::oneshot;
12	
13	use crate::config::HostConfig;
14	
15	/// One host serves any number of rank-level `OffloadEngine`s. That is the
16	/// DP-rank sharing model: each rank registers its own GPU arenas as its own
17	/// pegaflow *instance*, but blocks land in the one host tier keyed by
18	/// `(namespace, hash)` — with a shared namespace, any rank restores what any
19	/// rank saved. Callers share a namespace only when their KV is
20	/// interchangeable across instances: for replicated-weight DP ranks that
21	/// holds to the same tolerance as reusing a rank's own prefix cache (the
22	/// bytes may differ by FP reduction order across batch shapes, exactly like
23	/// two local recomputations of the same prefix would).
24	///
25	/// Dropping the last handle drops the [`Runtime`], which abandons any
26	/// in-flight fire-and-forget saves (acceptable — the host tier is a cache)
27	/// and stops the P2P serving tasks; peers degrade to their own local
28	/// prefill. In-flight `OffloadEngine::flush_saves_then` barriers are
29	/// cancelled too, dropping their `then` callbacks unrun.
30	pub struct OffloadHost {
31	    pub(crate) engine: Arc<PegaEngine>,
32	    pub(crate) runtime: Runtime,
33	    /// `Some` when P2P is on: resolves the P2P serving tasks (gRPC transfer
34	    /// service + transfer-lock GC) on drop.
35	    #[allow(dead_code)]
36	    p2p_shutdown: Option<oneshot::Sender<()>>,
37	}
38	
39	impl OffloadHost {
40	    pub(crate) fn new(config: HostConfig) -> Result<Arc<Self>, EngineError> {
41	        let runtime = tokio::runtime::Builder::new_multi_thread()
42	            .worker_threads(config.runtime_threads.max(1))
43	            .enable_all()
44	            .build()
45	            .map_err(|e| EngineError::Storage(format!("offload runtime build: {e}")))?;
46	
47	        let mut storage_config = StorageConfig::default();
48	        if let Some(p2p) = &config.p2p {
49	            if p2p.rdma_nics.is_empty() {
50	                return Err(EngineError::InvalidArgument(
51	                    "P2P requires at least one RDMA NIC".into(),
52	                ));
53	            }
54	            storage_config.rdma_nic_names = Some(p2p.rdma_nics.clone());
55	            storage_config.metaserver_addr = Some(p2p.metaserver_addr.clone());
56	            storage_config.advertise_addr = Some(p2p.advertise_addr.clone());
57	        }
58	        // pegaflow's MetaServerClient spawns its background registration loop
59	        // with tokio::spawn, so the engine must be built inside our runtime.
60	        let engine = {
61	            let _guard = runtime.enter();
62	            Arc::new(PegaEngine::new_with_config(
63	                config.pinned_pool_bytes,
64	                config.use_hugepages,
65	                storage_config,
66	            )?)
67	        };
68	
69	        // P2P serving side: peers discovered us via the MetaServer and dial
70	        // `advertise_addr` for the RDMA handshake + block queries. Same
71	        // lifecycle as the engine — shut down (via the oneshot) on drop.
72	        let p2p_shutdown = match config.p2p {
73	            Some(p2p) => {
74	                let listen: std::net::SocketAddr = p2p.advertise_addr.parse().map_err(|e| {
75	                    EngineError::InvalidArgument(format!(
76	                        "P2P advertise_addr {:?} is not a socket address: {e}",
77	                        p2p.advertise_addr
78	                    ))
79	                })?;
80	                let (shutdown_tx, shutdown_rx) = oneshot::channel::<()>();
81	                let serve_engine = Arc::clone(&engine);
82	                let (ready_tx, ready_rx) = std::sync::mpsc::channel::<Result<(), String>>();
83	                runtime.spawn(async move {
84	                    // Bind eagerly so startup fails loud on a taken port
85	                    // instead of P2P silently never serving.
86	                    let bound = tokio::net::TcpListener::bind(listen).await;
87	                    let listener = match bound {
88	                        Ok(l) => {
89	                            let _ = ready_tx.send(Ok(()));
90	                            l
91	                        }
92	                        Err(e) => {
93	                            let _ = ready_tx.send(Err(format!("bind {listen}: {e}")));
94	                            return;
95	                        }
96	                    };
97	                    let incoming = tokio_stream::wrappers::TcpListenerStream::new(listener);
98	                    if let Err(e) =
99	                        P2pTransferService::serve_with_incoming(serve_engine, incoming, async {
100	                            let _ = shutdown_rx.await;
101	                        })
102	                        .await
103	                    {
104	                        log::error!("P2P transfer service exited: {e}");
105	                    }
106	                });
107	                ready_rx
108	                    .recv()
109	                    .map_err(|_| EngineError::Storage("P2P serve task died at startup".into()))?
110	                    .map_err(EngineError::Storage)?;
111	
112	                // Background GC, mirroring pegaflow-server's task. Two sweeps:
113	                // expired transfer locks (a crashed peer must not pin our
114	                // blocks past the lock timeout) and stale prefetch state — an
115	                // abandoned remote fetch (request dropped mid-RemoteFetch, or
116	                // the executor's re-query deadline fired) leaves an orphaned
117	                // entry whose completed task pins its fetched blocks in the
118	                // pinned pool until this sweep drops it.
119	                let gc_engine = Arc::clone(&engine);
120	                runtime.spawn(async move {
121	                    const STALE_MAX_AGE: std::time::Duration = std::time::Duration::from_mins(5);
122	                    let mut tick = tokio::time::interval(std::time::Duration::from_mins(1));
123	                    tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
124	                    loop {
125	                        tick.tick().await;
126	                        let expired = gc_engine.gc_expired_transfer_locks();
127	                        if expired > 0 {
128	                            log::warn!("P2P GC released {expired} expired transfer locks");
129	                        }
130	                        let (stale, failed) = gc_engine
131	                            .gc_stale_inflight(STALE_MAX_AGE, STALE_MAX_AGE)
132	                            .await;
133	                        if stale > 0 || failed > 0 {
134	                            log::info!(
135	                                "P2P GC dropped {stale} stale prefetch entries, \
136	                                 {failed} failed-remote markers"
137	                            );
138	                        }
139	                    }
140	                });
141	                log::info!(
142	                    "KV offload P2P enabled: serving on {listen}, metaserver={}",
143	                    p2p.metaserver_addr
144	                );
145	                Some(shutdown_tx)
146	            }
147	            None => None,
148	        };
149	
150	        Ok(Arc::new(Self {
151	            engine,
152	            runtime,
153	            p2p_shutdown,
154	        }))
155	    }
156	}
